#include <fstream>
#include <vector>
#include <cstring>
#include <stdexcept>
#include "npusim_chiplet_runtime.h"
#include "sync_protocol.h"
#include "apis_c.h"
#include "sim_api.h"
extern "C" int rms(const uint16_t*,uint16_t*,float*,int,int,float);
std::vector<uint16_t> readfile(std::string p){std::ifstream f(p,std::ios::binary|std::ios::ate);auto size=f.tellg();if(size<=0)throw std::runtime_error("file");std::vector<uint16_t>v(size_t(size)/2);f.seekg(0);f.read((char*)v.data(),size);return v;}
void pipeio(int fd,char*p,size_t n,bool wr){if(fd<0)throw std::runtime_error("pipe open");while(n){auto k=wr?write(fd,p,n):read(fd,p,n);if(k<=0)throw std::runtime_error("pipe EOF");n-=k;p+=k;}close(fd);}
int main(int argc,char**argv){std::string root=argv[2];if(std::string(argv[1])=="cpu"){auto scale=readfile(root+"/scale.bin");SimRoiStart();for(auto phase:{"prefill","decode"}){auto x=readfile(root+"/"+phase+"_x.bin"),a=readfile(root+"/"+phase+"_a.bin"),gold=readfile(root+"/"+phase+"_gold.bin");std::vector<uint16_t>payload=x;payload.insert(payload.end(),a.begin(),a.end());payload.insert(payload.end(),scale.begin(),scale.end());if(InterChiplet::sendMessage(1,0,0,0,payload.data(),payload.size()*2)<0)return 8;std::vector<uint16_t>out(gold.size());if(InterChiplet::receiveMessage(0,0,1,0,out.data(),out.size()*2)<0)return 9;if(out!=gold)return 10;std::ofstream(root+"/"+phase+"_ACTUAL.bin",std::ios::binary).write((char*)out.data(),out.size()*2);}SimRoiEnd();std::ofstream(root+"/CPU_PASS.json")<<"{\"state\":\"PASS_UNIFIED_REAL_PREFILL_DECODE_RESIDUAL_NORM\",\"prefill_elements\":38912,\"decode_elements\":2048}";return 0;}
NPUSim::NPUConfig c;c.external_memory_enable=true;c.external_memory_model="chiplet";c.dram_transaction_bytes=32;c.dram_size_bytes=536870912;c.dram_chiplet_x=2;c.dram_chiplet_y=0;c.dram_chiplet_burst_bytes=4096;c.dram_chiplet_region_bytes=536870912;c.dram_chiplet_grid_cols=3;c.intra_delay_enable=false;c.mac_unit_count=4096;c.sram_per_mac_bytes=1024;c.vector_ops_per_cycle=16;c.reduce_ops_per_cycle=16;c.sram_bandwidth_bytes_per_cycle=256;c.activation_dtype=c.weight_dtype=c.output_dtype=NPUSim::TensorDType::kBf16;c.accumulator_dtype=NPUSim::TensorDType::kFp32;NPUSim::ChipletNpuRuntimeOptions opt;opt.self_x=1;opt.self_y=0;opt.report_directory=root+"/npu_reports";NPUSim::ChipletNpuRuntime rt(c,opt);std::ofstream audit(root+"/schedule.csv");audit<<"phase,id,ready,start,complete\n";
for(int phase=0;phase<2;++phase){size_t n=phase==0?38912:2048;std::vector<uint16_t>data(n*2+2048);auto pipe=InterChiplet::receiveSync(0,0,1,0);pipeio(open(pipe.c_str(),O_RDONLY),(char*)data.data(),data.size()*2,false);auto recv=InterChiplet::readSync(rt.chipCycle(),0,0,1,0,data.size()*2,0);if(recv<0)return 11;rt.chipCycle()=std::max(rt.chipCycle(),(unsigned long long)recv);rt.store(1048576,data.data(),data.size()*2,"real_CPU_payload");std::vector<uint8_t>loaded(data.size()*2),result(n*2);NPUSim::NpuEventRecorder rec;auto load=rec.dmaLoad(phase+1,1048576,data.size()*2);auto compute=rec.vectorCompute(phase+1,n*8,{load});auto store=rec.dmaStore(phase+1,2097152,n*2,{compute});NPUSim::ChipletDmaCallbackOptions dma;NPUSim::ChipletDmaPayloadBinding lb;lb.logical_id=load;lb.address=1048576;lb.bytes=data.size()*2;lb.load_destination=&loaded;lb.after_load=[&](){auto p=(const uint16_t*)loaded.data();std::vector<uint16_t>sum(n),norm(n);for(size_t i=0;i<n;++i)sum[i]=NPUSim::floatToBf16Bits(NPUSim::bf16BitsToFloat(p[i])+NPUSim::bf16BitsToFloat(p[n+i]));std::vector<float>stats(n/2048*3);if(rms(sum.data(),norm.data(),stats.data(),n/2048,2048,1e-6))throw std::runtime_error("norm");auto y=(uint16_t*)result.data();for(size_t i=0;i<n;++i)y[i]=NPUSim::floatToBf16Bits(NPUSim::bf16BitsToFloat(norm[i])*NPUSim::bf16BitsToFloat(p[2*n+i%2048]));};NPUSim::ChipletDmaPayloadBinding sb;sb.logical_id=store;sb.address=2097152;sb.bytes=n*2;sb.store_source=[&]()->const std::vector<uint8_t>&{return result;};dma.payload_bindings={lb,sb};dma.gate_on_external_completion=true;auto schedule=rt.scheduleProgram(rec.events(),dma);for(auto&e:schedule.entries)audit<<phase<<","<<e.event.id<<","<<e.ready_cycle<<","<<e.start_cycle<<","<<e.complete_cycle<<"\n";std::vector<uint8_t>back(n*2);rt.load(2097152,back.data(),back.size(),"committed_result_for_CPU");if(back!=result)return 12;auto name=InterChiplet::sendSync(1,0,0,0);pipeio(open(name.c_str(),O_WRONLY),(char*)back.data(),back.size(),true);auto sent=InterChiplet::writeSync(rt.chipCycle(),1,0,0,0,back.size(),0);if(sent<0)return 13;rt.chipCycle()=std::max(rt.chipCycle(),(unsigned long long)sent);}
rt.shutdown();InterChiplet::sendCycleCmd(rt.chipCycle());return 0;}
